class_name StoryLoader
extends RefCounted


func load_first_chapter() -> Dictionary:
	# Errore di maiuscole/minuscole nel percorso
	var path := "res://Story/Chapters/chapter_01.json"
	if not FileAccess.file_exists(path):
		return {}
	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		return {}
	var json_data: Variant = JSON.parse_string(file.get_as_text())
	if json_data is Dictionary:
		return json_data
	return {}

