class_name SaveSystem
extends RefCounted


func save_progress(data: Dictionary) -> bool:
	var path := "user://progress.json"
	var file := FileAccess.open(path, FileAccess.WRITE)
	if not file:
		return false
	file.store_string(JSON.stringify(data))
	file.close()
	return true
